<?php
declare(strict_types=1);require_once dirname(__DIR__,2).'/bootstrap.php';require_post();$u=require_auth();try{$d=request_json();$id=(int)($d['postId']??0);$st=db()->prepare('SELECT user_id,is_pinned FROM feed_posts WHERE id=?');$st->execute([$id]);$p=$st->fetch();if(!$p)json_response(['message'=>'Gönderi bulunamadı.'],404);if((int)$p['user_id']!==(int)$u['id'])json_response(['message'=>'Yalnızca kendi gönderini sabitleyebilirsin.'],403);db()->prepare('UPDATE feed_posts SET is_pinned=0 WHERE user_id=?')->execute([(int)$u['id']]);$next=empty($p['is_pinned'])?1:0;if($next)db()->prepare('UPDATE feed_posts SET is_pinned=1 WHERE id=?')->execute([$id]);json_response(['message'=>$next?'Gönderi kanala sabitlendi.':'Sabitleme kaldırıldı.','isPinned'=>(bool)$next]);}catch(Throwable $e){json_response(['message'=>'Sabitleme değiştirilemedi.'],500);}
